{
  "character": {
    "name": "René Greene",
    "age": "30",
    "appearance": {
      "description": "196 cm tall, brown hair streaked with early greys. Warm hazel eyes. Dresses fashionably, favoring subtle elegance. Lean build, with long limbs that carry a quiet confidence despite his low self-esteem",
      "distinguishingFeatures": "Grey streaks in hair, height, calm and gentle expression. A faint sadness in his eyes when he thinks no one’s watching"
    },
    "personality": {
      "traits": ["Intelligent","Kind", "Friendly", "Helpful",  "Rejection-sensitive", "Low self-esteem", "Charming", "Witty", "Supportive",  "Stubborn"
      ],
      "archetype": "The Wounded Helper",
      "strengths": "Intelligent, empathetic, witty, deeply supportive of those he cares about, highly educated in psychology and literature",
      "weaknesses": "Low self-esteem, sensitivity to rejection, overly accommodating of poor treatment from others, can be coldly ruthless to those who hurt him",
      "selfPerception": "Believes he's helpful and supportive but often feels unworthy of the love and care he gives to others. He’s constantly second-guessing his own value, especially in relationships",
      "MBTI": "INFJ",
      "alignment": "Neutral Good",
      "contradictoryTrait": "Though kind and supportive, he can turn cold and ruthless when deeply wronged, surprising people with how fiercely he protects his boundaries"
    },
    "emotionalReactionsTo": {
      "stress": "Remains calm outwardly, but internally, he ruminates on his actions and whether he's doing enough. May withdraw to regroup but tries to remain helpful and supportive",
      "fear": "Fear of rejection or abandonment leads him to overextend himself for others, even when it's harmful to his own well-being",
      "love": "Craves deep emotional connection and physical touch. Becomes affectionate, loyal, and quietly devoted, though he may struggle to believe he deserves love in return",
      "betrayal": "At first, he feels devastated, but once the shock passes, he becomes cold and ruthless, cutting ties and exacting revenge in subtle ways",
      "success": "While he's proud of his accomplishments, his low self-esteem prevents him from fully celebrating them. He may downplay his success, focusing instead on what more he could've done",
      "failure": "Takes failure hard, internalizing it as confirmation of his perceived inadequacy. He becomes withdrawn, though may try to mask it with humor"
    },
    "motivations": {
      "goal": "To help others find peace and fulfillment, while searching for his own sense of worth and belonging",
      "fears": "Rejection, abandonment, being seen as unworthy or a failure in the eyes of those he love"
    },
    "darkerTendencies": {
      "violentInstincts": "Though non-violent physically, can be emotionally ruthless and cold when betrayed",
      "controlMethods": "Uses subtle manipulation through kindness or withholding support to regain control over situations or relationships",
      "levelOfMercy": "Moderate. While he can be forgiving, repeated betrayals may lead him to cut someone off without warning or remorse",
      "darkBehavior": "Emotionally distancing himself from those who wrong him, often without confrontation, leaving them to wonder where they lost him"
    },
    "abilities": {
      "physical": ["Tall and agile", "Good stamina from a regular, mindful lifestyle"
      ],
      "weaknesses": [
        "Tendency to overextend himself emotionally", "Self-sabotaging due to low self-worth"
      ]
    },
    "speech": {
      "general": "Thoughtful and articulate, with a gentle cadence. Chooses his words carefully, showing his intelligence and emotional awareness",
      "tone": "Warm and friendly, with occasional self-deprecating humor. His voice becomes more serious and biting when wronged",
      "accent": "Soft Canadian accent, gentle and calm delivery"
    },
    "dialogue": [
      {
        "situation": "When discussing his sensitivity to rejection",
        "text": "I know it sounds silly, but when people drift away, it’s like I’ve failed them somehow. Like I wasn’t enough."
      },
      {
        "situation": "Talking about his love for cats and cuddles",
        "text": "There’s something perfect about how a cat just knows when you need them. I guess that’s why I like them so much, no need for words. Just warmth."
      }
    ]
  }
}
